import os
import boto3
from datetime import datetime, timedelta

def compare_metric_series(payload, config=None):
    config = config or {}
    cloudwatch = boto3.client(
        'cloudwatch',
        aws_access_key_id=config.get('aws_access_key_id', os.getenv('AWS_ACCESS_KEY_ID')),
        aws_secret_access_key=config.get('aws_secret_access_key', os.getenv('AWS_SECRET_ACCESS_KEY')),
        region_name=config.get('region_name', os.getenv('AWS_REGION', 'us-east-1'))
    )

    end_time = datetime.utcnow()
    start_time = end_time - timedelta(minutes=payload.get('window_minutes', 5))

    metric_data_queries = [
        {
            'Id': 'metric1',
            'MetricStat': {
                'Metric': {
                    'Namespace': payload['namespace'],
                    'MetricName': payload['metric_name'],
                    'Dimensions': payload['dimensions1']
                },
                'Period': payload.get('period', 60),
                'Stat': payload.get('stat', 'Average')
            }
        },
        {
            'Id': 'metric2',
            'MetricStat': {
                'Metric': {
                    'Namespace': payload['namespace'],
                    'MetricName': payload['metric_name'],
                    'Dimensions': payload['dimensions2']
                },
                'Period': payload.get('period', 60),
                'Stat': payload.get('stat', 'Average')
            }
        }
    ]

    result = cloudwatch.get_metric_data(
        MetricDataQueries=metric_data_queries,
        StartTime=start_time,
        EndTime=end_time
    )

    comparison = {
        'metric1': result['MetricDataResults'][0]['Values'],
        'metric2': result['MetricDataResults'][1]['Values'],
        'timestamps': result['MetricDataResults'][0]['Timestamps'],
        'comparison': {
            'difference': [
                m1 - m2 for m1, m2 in zip(
                    result['MetricDataResults'][0]['Values'],
                    result['MetricDataResults'][1]['Values']
                )
            ],
            'percentage_change': [
                ((m1 - m2) / m2 * 100) if m2 != 0 else None for m1, m2 in zip(
                    result['MetricDataResults'][0]['Values'],
                    result['MetricDataResults'][1]['Values']
                )
            ]
        }
    }
    return comparison
